DO $tests$
DECLARE
  n integer;
BEGIN
  -- Fourth assignment exceeds the maximum of six weekly periods, so the
  -- entire batch, including the first three valid rows, must roll back.
  BEGIN
    PERFORM public.assign_professor_turmas_disciplina_batch(
      '10000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', '80000000-0000-0000-0000-000000000001',
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000001','curso_matriz_id','a0000000-0000-0000-0000-000000000005'),
        pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000002','curso_matriz_id','a0000000-0000-0000-0000-000000000008'),
        pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000003','curso_matriz_id','a0000000-0000-0000-0000-000000000009'),
        pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000004','curso_matriz_id','a0000000-0000-0000-0000-000000000005')
      )
    );
    RAISE EXCEPTION 'EXPECTED_WORKLOAD_BLOCK';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'ASSIGN_PROF_CARGA_EXCEEDED%' THEN RAISE; END IF;
  END;

  SELECT count(*) INTO n FROM public.turma_disciplinas_professores
  WHERE escola_id='10000000-0000-0000-0000-000000000001' AND professor_id='40000000-0000-0000-0000-000000000001'
    AND turma_id IN ('b0000000-0000-0000-0000-000000000001','b0000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003','b0000000-0000-0000-0000-000000000004');
  IF n <> 0 THEN RAISE EXCEPTION 'FAILED_BATCH_WAS_PARTIAL: %', n; END IF;

  SELECT public.assign_professor_turmas_disciplina_batch(
    '10000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001', '80000000-0000-0000-0000-000000000001',
    pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000001','curso_matriz_id','a0000000-0000-0000-0000-000000000005'),
      pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000002','curso_matriz_id','a0000000-0000-0000-0000-000000000008'),
      pg_catalog.jsonb_build_object('turma_id','b0000000-0000-0000-0000-000000000003','curso_matriz_id','a0000000-0000-0000-0000-000000000009')
    )
  ) INTO n;
  IF n <> 3 THEN RAISE EXCEPTION 'EXPECTED_3_CURRENT_ASSIGNMENTS, GOT %', n; END IF;

  -- The administrative read shows 3 distinct assignments, NOT the old
  -- 2025 link, and not each matrix version counted several times.
  SELECT count(*) INTO n
  FROM public.get_teacher_assignments_by_profiles(
    '10000000-0000-0000-0000-000000000001', ARRAY['30000000-0000-0000-0000-000000000001'::uuid]
  );
  IF n <> 3 THEN RAISE EXCEPTION 'ROSTER_NOT_YEAR_SCOPED: %', n; END IF;

  BEGIN
    PERFORM public.assign_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000005', 'a0000000-0000-0000-0000-000000000001', '40000000-0000-0000-0000-000000000001');
    RAISE EXCEPTION 'EXPECTED_HISTORICAL_REJECTION';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'ASSIGN_PROF_MATRIZ_ANO_INCOMPATIVEL%' THEN RAISE; END IF;
  END;

  BEGIN
    PERFORM public.assign_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000002', '40000000-0000-0000-0000-000000000001');
    RAISE EXCEPTION 'EXPECTED_DRAFT_REJECTION';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'ASSIGN_PROF_MATRIZ_ANO_INCOMPATIVEL%' THEN RAISE; END IF;
  END;

  BEGIN
    PERFORM public.assign_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000006', 'a0000000-0000-0000-0000-000000000009', '40000000-0000-0000-0000-000000000001');
    RAISE EXCEPTION 'EXPECTED_EXISTING_OWNER_REJECTION';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'ASSIGN_PROF_ALREADY_ASSIGNED%' THEN RAISE; END IF;
  END;

  SELECT count(*) INTO n FROM public.turma_disciplinas_professores
  WHERE escola_id='10000000-0000-0000-0000-000000000001' AND turma_id='b0000000-0000-0000-0000-000000000006' AND professor_id='40000000-0000-0000-0000-000000000002';
  IF n <> 1 THEN RAISE EXCEPTION 'SILENT_TEACHER_REPLACEMENT'; END IF;
END $tests$;

