DO $tests$
DECLARE
  v_before_id bigint;
  v_after_id bigint;
  v_count integer;
BEGIN
  SELECT id INTO v_before_id FROM public.turma_disciplinas_professores
    WHERE turma_id='b0000000-0000-0000-0000-000000000002';
  UPDATE public.teachers SET carga_horaria_maxima=2
    WHERE id='41000000-0000-0000-0000-000000000002';
  BEGIN
    PERFORM public.trocar_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001',
      'b0000000-0000-0000-0000-000000000002',
      'a0000000-0000-0000-0000-000000000008',
      '40000000-0000-0000-0000-000000000001',
      '40000000-0000-0000-0000-000000000002');
    RAISE EXCEPTION 'EXPECTED_REPLACEMENT_WORKLOAD_ERROR';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'TEACHER_REPLACE_WORKLOAD_EXCEEDED%' THEN RAISE; END IF;
  END;
  UPDATE public.teachers SET carga_horaria_maxima=30
    WHERE id='41000000-0000-0000-0000-000000000002';

  BEGIN
    PERFORM public.trocar_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001',
      'b0000000-0000-0000-0000-000000000002',
      'a0000000-0000-0000-0000-000000000008',
      '40000000-0000-0000-0000-000000000001',
      '40000000-0000-0000-0000-000000000002');
    RAISE EXCEPTION 'EXPECTED_REPLACEMENT_SCHEDULE_ERROR';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'TEACHER_REPLACE_SCHEDULE_CONFLICT%' THEN RAISE; END IF;
  END;
  IF EXISTS(SELECT 1 FROM public.audit_logs) THEN RAISE EXCEPTION 'FAILED_REPLACEMENT_AUDITED'; END IF;

  UPDATE public.quadro_horarios SET slot_id='e0000000-0000-0000-0000-000000000005'
    WHERE id='f0000000-0000-0000-0000-000000000004';
  PERFORM public.trocar_professor_turma_disciplina_atomic(
    '10000000-0000-0000-0000-000000000001',
    'b0000000-0000-0000-0000-000000000002',
    'a0000000-0000-0000-0000-000000000008',
    '40000000-0000-0000-0000-000000000001',
    '40000000-0000-0000-0000-000000000002');

  SELECT id INTO v_after_id FROM public.turma_disciplinas_professores
    WHERE turma_id='b0000000-0000-0000-0000-000000000002'
      AND professor_id='40000000-0000-0000-0000-000000000002';
  IF v_after_id IS NULL OR v_before_id <> v_after_id THEN
    RAISE EXCEPTION 'SHARED_ASSIGNMENT_ID_LOST';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.turma_disciplinas
    WHERE turma_id='b0000000-0000-0000-0000-000000000002'
      AND curso_matriz_id='a0000000-0000-0000-0000-000000000008'
      AND professor_id <> '40000000-0000-0000-0000-000000000002'
  ) THEN RAISE EXCEPTION 'CANONICAL_ASSIGNMENT_NOT_UPDATED'; END IF;
  IF EXISTS(
    SELECT 1 FROM public.quadro_horarios
    WHERE turma_id='b0000000-0000-0000-0000-000000000002'
      AND professor_id <> '40000000-0000-0000-0000-000000000002'
  ) THEN RAISE EXCEPTION 'PUBLISHED_TIMETABLE_NOT_UPDATED'; END IF;
  IF EXISTS(
    SELECT 1 FROM public.turma_disciplinas
    WHERE curso_matriz_id='a0000000-0000-0000-0000-000000000018'
      AND professor_id <> '40000000-0000-0000-0000-000000000001'
  ) THEN RAISE EXCEPTION 'DRAFT_TEACHER_HISTORY_CHANGED'; END IF;
  IF EXISTS(
    SELECT 1 FROM public.turma_disciplinas
    WHERE turma_id='b0000000-0000-0000-0000-000000000005'
      AND professor_id <> '40000000-0000-0000-0000-000000000001'
  ) THEN RAISE EXCEPTION 'HISTORICAL_TEACHER_LINK_CHANGED'; END IF;
  SELECT COUNT(*) INTO v_count FROM public.audit_logs
    WHERE escola_id='10000000-0000-0000-0000-000000000001'
      AND acao='PROFESSOR_ATRIBUICAO_TROCA'
      AND before->>'professor_id'='40000000-0000-0000-0000-000000000001'
      AND after->>'professor_id'='40000000-0000-0000-0000-000000000002';
  IF v_count <> 1 THEN RAISE EXCEPTION 'AUDIT_TRAIL_NOT_ATOMIC'; END IF;

  BEGIN
    PERFORM public.trocar_professor_turma_disciplina_atomic(
      '10000000-0000-0000-0000-000000000001',
      'b0000000-0000-0000-0000-000000000002',
      'a0000000-0000-0000-0000-000000000008',
      '40000000-0000-0000-0000-000000000001',
      '40000000-0000-0000-0000-000000000002');
    RAISE EXCEPTION 'EXPECTED_CAS_REJECTION';
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM NOT LIKE 'TEACHER_REPLACE_PREVIOUS_MISMATCH%' THEN RAISE; END IF;
  END;
END $tests$;

SELECT pg_catalog.set_config('app.test_uid', '20000000-0000-0000-0000-000000000002', true);
